async function main() {
  const page = await figma.getNodeByIdAsync("0:1");
  if (!page) {
    console.log("Page 0:1 not found");
    return;
  }

  // Let's traverse the page and collect all text content to understand the requirements
  function traverse(node, depth = 0) {
    let result = "";
    const indent = "  ".repeat(depth);
    if (node.type === "TEXT") {
      result += `${indent}[Text] "${node.name}": "${node.characters}"\n`;
    } else if (node.type === "FRAME" || node.type === "GROUP" || node.type === "SECTION" || node.type === "COMPONENT" || node.type === "INSTANCE") {
      result += `${indent}[${node.type}] "${node.name}" (${node.id})\n`;
      if ("children" in node) {
        for (const child of node.children) {
          result += traverse(child, depth + 1);
        }
      }
    } else {
      result += `${indent}[${node.type}] "${node.name}" (${node.id})\n`;
    }
    return result;
  }

  const logContent = traverse(page);
  console.log(logContent.substring(0, 8000)); // Print first 8000 chars
  if (logContent.length > 8000) {
    console.log("... (truncated, total length: " + logContent.length + ")");
    // Print remaining in parts if needed or just let it be if we got the main text
    console.log(logContent.substring(8000, 16000));
  }
}
main();

async function main() {
  const page = await figma.getNodeByIdAsync("0:1");
  if (!page) {
    console.log("Page 0:1 not found");
    return;
  }

  // Find all text nodes in page 0:1 and print their text content
  const textNodes = page.findAll(n => n.type === "TEXT");
  console.log(`Found ${textNodes.length} text nodes`);

  // Let's print text nodes sorted by their relative visual position (y, then x)
  const sortedTextNodes = [...textNodes].sort((a, b) => {
    const posA = a.absoluteTransform;
    const posB = b.absoluteTransform;
    const yA = posA ? posA[1][2] : 0;
    const yB = posB ? posB[1][2] : 0;
    const xA = posA ? posA[0][2] : 0;
    const xB = posB ? posB[0][2] : 0;
    if (Math.abs(yA - yB) < 10) {
      return xA - xB;
    }
    return yA - yB;
  });

  for (const node of sortedTextNodes) {
    console.log(`Node [${node.id}] (${node.name}):\n"${node.characters}"\n-------------------`);
  }
}
main();

async function main() {
