  const sortedTextNodes = [...textNodes].sort((a, b) => {
    const posA = a.absoluteRenderBounds || {y: 0, x: 0};
    const posB = b.absoluteRenderBounds || {y: 0, x: 0};
    if (Math.abs(posA.y - posB.y) < 20) {
      return posA.x - posB.x;
