(async () => {
  const page = await figma.getNodeByIdAsync("1:4");
  if (!page) return "Page 1:4 not found";

  function listAllMediaComponents(node, depth = 0) {
    let result = [];
    if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") {
      result.push({ id: node.id, name: node.name, type: node.type });
    }
    if ("children" in node) {
      for (const child of node.children) {
        result = result.concat(listAllMediaComponents(child, depth + 1));
      }
    }
    return result;
  }

  const mediaList = listAllMediaComponents(page);
  return `Total media components found: ${mediaList.length}\n` + JSON.stringify(mediaList, null, 2);
})()

