(async () => {
  // 1. Load required fonts
  await figma.loadFontAsync({ family: "Archivo Black", style: "Regular" });
  await figma.loadFontAsync({ family: "Plus Jakarta Sans", style: "Regular" });
  await figma.loadFontAsync({ family: "Plus Jakarta Sans", style: "Medium" });
  await figma.loadFontAsync({ family: "Plus Jakarta Sans", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Plus Jakarta Sans", style: "Bold" });

  const wsPage = await figma.getNodeByIdAsync("6:2");
  await figma.setCurrentPageAsync(wsPage);

  // Map of media components
  const mediaPage = await figma.getNodeByIdAsync("1:4");
  const mediaMap = {};
  function findMedia(node) {
    if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") {
      mediaMap[node.name] = node;
    }
    if ("children" in node) {
      for (const c of node.children) findMedia(c);
    }
  }
  findMedia(mediaPage);

  function getInstance(name, width, height) {
    const comp = mediaMap[name];
    if (!comp) {
      // Fallback rectangle if media missing
      const r = figma.createFrame();
      r.name = name;
      r.resize(width || 100, height || 100);
      r.fills = [{ type: 'SOLID', color: { r: 0.9, g: 0.9, b: 0.9 } }];
      return r;
    }
    const inst = comp.createInstance();
    if (width && height) {
      inst.resize(width, height);
    }
    return inst;
  }

  return `Loaded ${Object.keys(mediaMap).length} media components into map!`;
})()

(async () => {
  // We need to inspect the original Text Field layout so we can recreate and customize it nicely
  const page = await figma.getNodeByIdAsync("1:3");
  const comp = page.children.find(n => n.name === "Components");
  const textField = comp.children.find(n => n.name === "Text Field");

  function inspectNode(node) {
    let desc = `[${node.type}] "${node.name}" (${node.id})\n`;
    if (node.type === "TEXT") {
      desc += `  - Characters: "${node.characters}"\n`;
      desc += `  - FontSize: ${node.fontSize}\n`;
      desc += `  - FontName: ${JSON.stringify(node.fontName)}\n`;
    }
    if ("fills" in node) {
      desc += `  - Fills: ${JSON.stringify(node.fills)}\n`;
    }
    if ("layoutMode" in node) {
      desc += `  - AutoLayout: ${node.layoutMode}, padding: L:${node.paddingLeft} R:${node.paddingRight} T:${node.paddingTop} B:${node.paddingBottom}, spacing: ${node.itemSpacing}\n`;
    }
    if ("children" in node) {
      for (const c of node.children) {
        desc += "  " + inspectNode(c).split("\n").join("\n  ") + "\n";
      }
    }
    return desc;
  }

  return inspectNode(textField);
})()

