  function createRatingNode(score) {
    const row = figma.createFrame();
    row.name = "Rating";
    row.fills = [];
    row.layoutMode = "HORIZONTAL";
    row.counterAxisAlignItems = "CENTER";
    row.itemSpacing = 4;

    const fullStars = Math.floor(score);
    const hasHalf = (score % 1 !== 0);

    for (let i = 0; i < 5; i++) {
      if (i < fullStars) {
        row.appendChild(getInstance("Icon_Star", 18, 18));
      } else if (i === fullStars && hasHalf) {
        row.appendChild(getInstance("Icon_Star_Half", 18, 18));
      } else {
        const emptyStar = getInstance("Icon_Star", 18, 18);
        emptyStar.fills = [{ type: 'SOLID', color: { r: 0.8, g: 0.8, b: 0.8 } }];
        row.appendChild(emptyStar);
      }
    }

    const t = figma.createText();
    t.fontName = { family: "Plus Jakarta Sans", style: "Regular" };
    t.fontSize = 14;
    t.characters = `${score.toFixed(1)}/5`;
    t.fills = [{ type: 'SOLID', color: C.grayText }];
    row.appendChild(t);

    return row;
  }

