  function findMedia(node) {
    if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") {
      mediaMap[node.name] = node;
    }
    if ("children" in node) {
      for (const c of node.children) findMedia(c);
    }
  }
  findMedia(mediaPage);

  function getInstance(name, width, height) {
    const comp = mediaMap[name];
    if (!comp) {
      const r = figma.createFrame();
      r.name = name;
      r.resize(width || 24, height || 24);
      r.fills = [{ type: 'SOLID', color: { r: 0.9, g: 0.9, b: 0.9 } }];
      return r;
    }
    const inst = comp.createInstance();
    if (width && height) {
      inst.resize(width, height);
    }
    return inst;
  }

