(async () => {
  // Let's set up the prototype connection triggers carefully!
  // We'll skip self-navigation connections (source frame === target frame) because they are redundant and cause Figma errors.

  const wsPage = await figma.getNodeByIdAsync("6:2");
  const frames = {};
  for (const child of wsPage.children) {
    if (child.type === "FRAME") {
      frames[child.name] = child;
    }
  }

  const home = frames["01_Home"];
  const cat = frames["02_Category"];
  const prod = frames["03_Product"];
  const cart = frames["04_Cart"];

  let wireCount = 0;

  function findNodesByTrigger(parent, nameSub) {
    const results = [];
    function traverse(node) {
      if (node.name && node.name.includes(nameSub)) {
        results.push(node);
      }
      if ("children" in node) {
        for (const c of node.children) traverse(c);
      }
    }
    traverse(parent);
    return results;
  }

  function wire(source, target) {
    // Avoid wiring a node to its own parent frame (self-navigation)
    let parentFrame = source;
    while (parentFrame && parentFrame.parent && parentFrame.parent.type !== "PAGE") {
      parentFrame = parentFrame.parent;
    }
    if (parentFrame.id === target.id) {
      return; // Skip self-navigation
    }

    source.reactions = [
      {
        trigger: { type: "ON_CLICK" },
        actions: [
          {
            type: "NODE",
            destinationId: target.id,
            navigation: "NAVIGATE",
            transition: null
          }
        ]
      }
    ];
    wireCount++;
  }

  // 1. Wiring 01_Home triggers
  const shopNows = findNodesByTrigger(home, "Button_ShopNow_Trigger");
  for (const s of shopNows) wire(s, cat);

  const viewAll1s = findNodesByTrigger(home, "Button_ViewAll1_Trigger");
  for (const v of viewAll1s) wire(v, cat);

  const viewAll2s = findNodesByTrigger(home, "Button_ViewAll2_Trigger");
  for (const v of viewAll2s) wire(v, cat);

  const casualTiles = findNodesByTrigger(home, "Casual Tile_Trigger");
  for (const c of casualTiles) wire(c, cat);

  const homeProdCards = findNodesByTrigger(home, "Product Card_Trigger");
  for (const p of homeProdCards) wire(p, prod);

  const homeCarts = findNodesByTrigger(home, "Icon_Cart_Trigger");
  for (const c of homeCarts) wire(c, cart);

  // 2. Wiring 02_Category triggers
  const catProdCards = findNodesByTrigger(cat, "Product Card_Trigger");
  for (const p of catProdCards) wire(p, prod);

  const catHomes = findNodesByTrigger(cat, "Breadcrumb_Home_Trigger");
  for (const h of catHomes) wire(h, home);

  const catCarts = findNodesByTrigger(cat, "Icon_Cart_Trigger");
  for (const c of catCarts) wire(c, cart);

  // 3. Wiring 03_Product triggers
  const prodAddCarts = findNodesByTrigger(prod, "Button_AddToCart_Trigger");
  for (const a of prodAddCarts) wire(a, cart);

  const prodHomes = findNodesByTrigger(prod, "Breadcrumb_Home_Trigger");
  for (const h of prodHomes) wire(h, home);

  const prodShops = findNodesByTrigger(prod, "Breadcrumb_Shop_Trigger");
  for (const s of prodShops) wire(s, cat);

  const prodCarts = findNodesByTrigger(prod, "Icon_Cart_Trigger");
  for (const c of prodCarts) wire(c, cart);

  // 4. Wiring 04_Cart triggers
  const cartHomes = findNodesByTrigger(cart, "Breadcrumb_Home_Trigger");
  for (const h of cartHomes) wire(h, home);

  const cartItems = findNodesByTrigger(cart, "Cart Line Item");
  for (const item of cartItems) wire(item, prod);

  const cartCarts = findNodesByTrigger(cart, "Icon_Cart_Trigger");
  for (const c of cartCarts) wire(c, cart);

  return `Wiring complete! Total reaction wires added: ${wireCount}`;
})()
